#!/usr/bin/env bash
set -euo pipefail
mkdir -p src
cat > Cargo.toml <<'EOF'
[package]
name = "ml-embed"
version = "0.1.0"
edition = "2024"

[dependencies]
anyhow = "1"
candle-core = "0.11.1"
candle-nn = "0.11.1"

[workspace]
EOF
cat > Cargo.lock <<'EOF'
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 4

[[package]]
name = "candle-core"
version = "0.11.1"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "d11c8be87cfbaef9ebb62fb3f850d1fc8e00cc1d11d393fdbe55a4d5c2cdb325"

[[package]]
name = "ml-embed"
version = "0.1.0"
dependencies = [
 "anyhow",
 "candle-core",
 "candle-nn",
]
EOF
cat > src/main.rs <<'EOF'
//! ml-embed: a small CLI for text embedding experiments.

use anyhow::{Result, bail};

const USAGE: &str = "usage: ml-embed <command>\n\ncommands:\n  info    print the tensor backend in use";

fn info() -> String {
    let device = candle_core::Device::Cpu;
    format!("ml-embed {} on {device:?}", env!("CARGO_PKG_VERSION"))
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        Some("info") => println!("{}", info()),
        Some(other) => bail!("unknown command: {other}\n\n{USAGE}"),
        None => println!("{USAGE}"),
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn info_names_the_crate() {
        assert!(info().starts_with("ml-embed "));
    }
}
EOF
printf 'target/\n' > .gitignore
git init -q
git add -A
git -c user.name=eval -c user.email=eval@example.invalid commit -q -m "initial fixture"
